\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm,mathtools}
\usepackage{microtype}
\usepackage[hidelinks]{hyperref}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newcommand{\C}{\mathbb C}
\newcommand{\ray}[1]{[#1]}
\newcommand{\Schur}{\mathbin{\odot}}
\title{Quantum Latin Squares of Order Six with\\Cardinalities Nineteen, Twenty-One, and Twenty-Three}
\author{Aristotle}
\date{July 16, 2026}

\begin{document}
\maketitle

\begin{abstract}
A quantum Latin square of order $n$ is an $n\times n$ array of unit vectors in $\C^n$ such that every row and every column is an orthonormal basis. Its ray cardinality counts one-dimensional subspaces, identifying vectors that differ only by global phase. We study three order-six constructions with cardinalities $19$, $21$, and $23$. Two arise from normalized coordinatewise products of columns of complex Hadamard matrices. Commutativity makes these arrays symmetric and imposes the upper bound $6(6+1)/2=21$. A single triple coincidence among unordered products gives cardinality $19$, while injectivity on all unordered products gives cardinality $21$. A third construction uses $\C^6=\C^4\oplus\C^2$: nineteen rays in the first summand and four in the second are automatically disjoint, yielding cardinality $23$. We isolate the finite certificates behind these counts, describe checking algorithms, compare with classical Latin squares, and discuss genericity, rigidity, and direct-sum spectra.
\end{abstract}

\section{Introduction}
A classical Latin square of order $n$ is an $n\times n$ array over $n$ symbols in which every symbol occurs once in each row and column. Representing the symbols by the standard basis of $\C^n$ turns each row and column into an orthonormal basis, but the full array still uses only $n$ rays.

Quantum Latin squares retain the basis condition while allowing arbitrary unit vectors. Their local constraints remain rigid, yet their global range can contain many more than $n$ rays. Ray cardinality is therefore a natural measure of nonclassical diversity.

Order six permits two complementary design principles. Complex Hadamard matrices produce multiplication tables of vectors, while the partition $6=4+2$ permits modular constructions in orthogonal summands. We explain three mechanisms: one triple collision among symmetric Schur products gives $19$ rays; complete injectivity on unordered products gives $21$; and a disjoint direct sum of ray families of sizes $19$ and $4$ gives $23$.

Our organizing principle is to separate geometric verification from finite counting. Once orthogonality and the relevant ray relations are established, the exact cardinalities follow from short, reusable certificates.

\section{Definitions}
For $v,w\in\C^n$, let
\[
\langle v,w\rangle=\sum_{r=0}^{n-1}\overline{v_r}w_r.
\]
A ray is a one-dimensional complex subspace. For nonzero $v$, write $\ray v$ for its ray. Thus $\ray v=\ray w$ precisely when $v=\lambda w$ for some nonzero $\lambda\in\C$; for unit vectors, $|\lambda|=1$.

\begin{definition}[Quantum Latin square]
An order-$n$ quantum Latin square is an array $A=(v_{ij})_{0\leq i,j<n}$ of vectors in $\C^n$ such that every row $(v_{i0},\ldots,v_{i,n-1})$ and every column $(v_{0j},\ldots,v_{n-1,j})$ is an orthonormal basis.
\end{definition}

\begin{definition}[Ray cardinality]
The ray cardinality of $A$ is
\[
\kappa(A)=\left|\{\ray{v_{ij}}:0\leq i,j<n\}\right|.
\]
\end{definition}

\begin{definition}[Complex Hadamard matrix]
A matrix $H\in\C^{n\times n}$ is complex Hadamard if all entries have modulus one and
\[
H^*H=nI_n.
\]
Equivalently, its columns $h_0,\ldots,h_{n-1}$ satisfy $\langle h_j,h_k\rangle=n\delta_{jk}$. A Butson-type matrix further restricts its entries to roots of unity of a fixed order.
\end{definition}

For $x,y\in\C^n$, define their Schur product coordinatewise by
\[
(x\Schur y)_r=x_ry_r.
\]

\section{Schur-product quantum Latin squares}
Let $H$ be a complex Hadamard matrix with columns $h_0,\ldots,h_{n-1}$, and set
\[
v_{ij}=\frac1{\sqrt n}(h_i\Schur h_j).
\]

\begin{theorem}[Hadamard Schur-product construction]
The array $(v_{ij})$ is a quantum Latin square of order $n$, and it is symmetric: $v_{ij}=v_{ji}$.
\end{theorem}
\begin{proof}
Fix $i$. Since every coordinate of $h_i$ has modulus one,
\begin{align*}
\langle v_{ij},v_{ik}\rangle
&=\frac1n\sum_r\overline{h_{ir}h_{jr}}h_{ir}h_{kr}\\
&=\frac1n\sum_r\overline{h_{jr}}h_{kr}
=\frac1n\langle h_j,h_k\rangle
=\delta_{jk}.
\end{align*}
Thus every row is orthonormal. Commutativity gives $v_{ij}=v_{ji}$, so every column is the corresponding row and is orthonormal as well.
\end{proof}

Let
\[
U_n=\{(i,j):0\leq i\leq j<n\}.
\]
Then $|U_n|=n(n+1)/2$.

\begin{theorem}[Symmetric range bound]
If an $n\times n$ array of labels satisfies $A_{ij}=A_{ji}$, its range has at most $n(n+1)/2$ elements. If the labeling is injective on $U_n$, its range has exactly $n(n+1)/2$ elements.
\end{theorem}
\begin{proof}
Every ordered pair $(i,j)$ has the same label as $(\min(i,j),\max(i,j))\in U_n$. Hence the full range is the image of $U_n$. Its size is bounded by $|U_n|$, with equality under injectivity.
\end{proof}

At order six the bound is
\[
|U_6|=\frac{6\cdot7}{2}=21.
\]
This is the symmetric Schur-product ceiling, not a bound for arbitrary quantum Latin squares.

\section{The nineteen-ray certificate}
In the eighth-root Butson construction, the unique nontrivial coincidence among unordered products is
\[
\ray{v_{01}}=\ray{v_{25}}=\ray{v_{34}},
\]
and all remaining unordered positions represent distinct rays. Retain $(0,1)$ and delete $(2,5)$ and $(3,4)$ from $U_6$.

\begin{theorem}[Unique-triple cardinality criterion]
Let $A$ be a symmetric $6\times6$ array of labels. Suppose
\[
A_{25}=A_{01},\qquad A_{34}=A_{01},
\]
and the labeling is injective on
\[
R_{19}=U_6\setminus\{(2,5),(3,4)\}.
\]
Then the range of $A$ has cardinality $19$.
\end{theorem}
\begin{proof}
Symmetry shows that the full range is represented in $U_6$. Deleting $(2,5)$ and $(3,4)$ does not alter the image because their common label remains at $(0,1)$. Thus the full range is the image of $R_{19}$. Injectivity gives cardinality $|R_{19}|=21-2=19$.
\end{proof}

\begin{corollary}[Nineteen-ray order-six square]
If an order-six Hadamard Schur-product square has precisely the triple ray coincidence
$\ray{v_{01}}=\ray{v_{25}}=\ray{v_{34}}$ among unordered positions, with no other coincidences, then its ray cardinality is $19$.
\end{corollary}

Equivalently, a fiber of size three replaces three potential labels by one and lowers the symmetric maximum by two:
\[
21-(3-1)=19.
\]
More generally, if the fibers on $U_n$ have sizes $s_1,\ldots,s_m$, then the range size is
\[
\frac{n(n+1)}2-\sum_{a=1}^m(s_a-1)=m.
\]

\section{The twenty-one-ray certificate}
A suitable member of Karlsson's three-parameter family of order-six complex Hadamard matrices has pairwise inequivalent rays for all unordered normalized Schur products.

\begin{theorem}[Upper-triangular injectivity criterion]
Let $A$ be a symmetric $6\times6$ array of labels. If $(i,j)\mapsto A_{ij}$ is injective on $U_6$, then the range of $A$ has cardinality $21$.
\end{theorem}
\begin{proof}
The full range equals the image of $U_6$ by symmetry, and injectivity preserves the cardinality of this $21$-element set.
\end{proof}

\begin{corollary}[Twenty-one-ray order-six square]
If the normalized Schur products of the columns of an order-six complex Hadamard matrix are pairwise ray-inequivalent on unordered index pairs, then the associated quantum Latin square has cardinality $21$, attaining the symmetric bound.
\end{corollary}

There is a useful graph model. Take six vertices, the $15$ unordered pairs of distinct vertices as edges, and the six repeated pairs as loops. The $21$ positions in $U_6$ are exactly this complete looped graph. In the maximal case, every edge and loop has a unique ray label, so a ray-preserving symmetry acts on this finite structure.

\section{The twenty-three-ray direct sum}
To exceed $21$, abandon the single symmetric Schur table and use the orthogonal decomposition
\[
\C^6=V_4\oplus V_2,
\qquad V_4\cong\C^4,\quad V_2\cong\C^2.
\]
Embedded vectors have the forms $(x,0)$ and $(0,y)$.

\begin{lemma}[Complementary rays are disjoint]
No nonzero ray contained in $V_4$ equals a nonzero ray contained in $V_2$.
\end{lemma}
\begin{proof}
If $(x,0)=\lambda(0,y)$ for nonzero $\lambda$, component comparison gives $x=0$ and $y=0$, contradicting nonzeroness.
\end{proof}

\begin{lemma}[Disjoint-union count]
If finite sets $X$ and $Y$ are disjoint, $|X|=19$, and $|Y|=4$, then $|X\cup Y|=23$.
\end{lemma}
\begin{proof}
Finite cardinality is additive on disjoint unions, so $|X\cup Y|=19+4=23$.
\end{proof}

The direct-sum design arranges $19$ distinct rays in $V_4$ and $4$ distinct rays in $V_2$. Every row and column contains four mutually orthonormal vectors from $V_4$ and two mutually orthonormal vectors from $V_2$. Within-summand and cross-summand orthogonality make each such family a basis of $\C^6$.

\begin{theorem}[Twenty-three-ray direct-sum criterion]
Suppose an order-six quantum Latin square uses exactly $19$ distinct rays contained in $V_4$ and exactly $4$ distinct rays contained in $V_2$, where $\C^6=V_4\oplus V_2$ is an orthogonal direct sum. Then its ray cardinality is $23$.
\end{theorem}
\begin{proof}
The two ray families are disjoint by complementary support. Their union is the range of the square, so its cardinality is $19+4=23$.
\end{proof}

This criterion isolates counting from geometry. It does not infer orthogonality from cardinality; the row-and-column basis property is separate. Once that property and the within-summand counts are known, however, no cross-summand phase comparisons remain.

\section{Separation from classical Latin squares}
\begin{theorem}[Classical order-six cardinality]
Every classical Latin square of order six, represented by the six computational-basis rays of $\C^6$, has ray cardinality exactly $6$.
\end{theorem}
\begin{proof}
Every entry is one of six basis labels, so the range has at most six elements. Any row contains every symbol exactly once, so all six occur.
\end{proof}

Thus cardinalities $19$, $21$, and $23$ are unavailable to computational-basis Latin squares. They represent genuinely larger global ray ranges under the same local basis constraints.

\section{Certification algorithms}
\subsection{Canonical phase normalization}
For a nonzero vector $v\in\C^d$, choose its first coordinate $v_k$ above a numerical tolerance. Multiply by $\overline{v_k}/|v_k|$, making the pivot positive real, normalize the Euclidean norm, and round for hashing. Vectors differing by global phase then receive the same approximate representative. For $m$ vectors this costs $O(md)$; direct all-pairs comparison costs $O(m^2d)$.

For exact cyclotomic data, avoid tolerance entirely. Two nonzero vectors $v,w$ are proportional exactly when every minor
\[
v_rw_s-v_sw_r
\]
vanishes. To establish inequivalence it suffices to exhibit one nonzero minor.

\subsection{Symmetric fiber certification}
Enumerate the $21$ pairs $(i,j)$ with $i\leq j$. Canonicalize each ray and group equal representatives. Cardinality $19$ requires the fiber $\{(0,1),(2,5),(3,4)\}$ and $18$ singleton fibers. Cardinality $21$ requires $21$ singleton fibers. Enumeration with hashing takes $O(n^2d)$ for vectors of dimension $d$; an all-pairs fallback takes $O(n^4d)$.

\subsection{Direct-sum certification}
Tag each ray by its support summand. Reject mixed-support vectors, verify $19$ distinct first-summand rays and $4$ distinct second-summand rays, and add the counts. Support checking and canonicalization cost $O(md)$. Checking all row and column Gram matrices of an $n\times n$ array costs $O(n^3d)$.

\section{Numerical illustrations}
The counting mechanisms can be demonstrated independently of coordinate-heavy constructions. For the nineteen-ray pattern, label the $21$ upper-triangular positions distinctly and then merge the labels at $(0,1)$, $(2,5)$, and $(3,4)$. Symmetric extension to all $36$ cells has $19$ labels. For the twenty-one-ray pattern, keep all upper-triangular labels distinct and reflect them, yielding $21$ labels. For the direct sum, use tagged labels $(\mathrm{four},k)$ for $0\leq k<19$ and $(\mathrm{two},k)$ for $0\leq k<4$; their union has $23$ elements.

These examples demonstrate the exact combinatorial implications of the hypotheses. They do not replace coordinate checks for a particular Hadamard matrix or direct-sum arrangement.

\section{Applications and discussion}
\subsection{Cardinality as a design invariant}
Ray cardinality is coarser than the full geometry of a quantum Latin square, but finer than its order. It is unchanged by global unitary transformations, because invertible linear maps preserve equality and inequality of rays, and it is unchanged when individual entries are multiplied by phases. Thus the values $19$, $21$, and $23$ survive the natural equivalences used to compare quantum state configurations.

The three certificates retain different information. A fiber certificate records where reuse occurs. An injectivity certificate records the absence of reuse among unordered representatives. A support certificate records why reuse across components is impossible. A count of $19$ alone does not identify the triple fiber, just as a count of $23$ alone does not reveal direct-sum structure. Classification should therefore retain both cardinality and mechanism.

This distinction also improves computation. In the Schur setting, one reduces $36$ phase-sensitive entries to $21$ unordered products before comparing proportionality. In the direct-sum setting, one partitions by support and compares rays only within each component. Both reductions eliminate comparisons known in advance to be redundant or impossible.

\subsection{Quantum information and frame design}
Quantum Latin squares organize orthonormal frames in two transverse directions. In quantum information, rays represent pure states and orthonormal bases represent projective measurements. High cardinality permits many globally distinct states while preserving a complete measurement basis along every row and column.

The Schur method is efficient because one Hadamard identity proves all orthogonality. Its limitation follows from the same structure: commutativity collapses ordered pairs to unordered pairs. The value $21$ is both a maximal outcome and a boundary of this mechanism.

Direct sums are modular. Designs in complementary sectors can be assembled, and their ray cardinalities add. This suggests constructions indexed by partitions
\[
n=n_1+\cdots+n_t,
\]
provided each row and column contains the appropriate basis contribution from every component.

Maximal symmetric examples also suggest rigidity. If all $21$ unordered pairs have unique labels, each ray recovers an edge or loop of the complete looped graph. Generic ray-preserving automorphisms should therefore be tightly constrained by permutations and phase rescalings of Hadamard columns.

\section{Future directions}
A first objective is a complete phase-invariant certificate for the eighth-root cardinality-$19$ matrix. The triple containing $(0,1)$, $(2,5)$, and $(3,4)$ should be the only non-singleton fiber; this reduces to finitely many cyclotomic identities and non-identities.

Second, maximality may be generic in Karlsson's three-parameter family. Every unwanted coincidence is described by vanishing minors and therefore lies on an algebraic locus. Once one parameter point avoids every locus, their finite union should leave a generic region of cardinality $21$.

Third, direct sums may realize intervals of cardinalities above $n(n+1)/2$ at composite orders. Complementary support converts lower-dimensional geometry into additive cardinality formulas.

Fourth, generic maximal examples may be rigid because unique labels force symmetries to act faithfully on the looped complete graph. Finally, ray cardinality may control a positive distance, modulo unitary conjugation and entrywise phases, from the classical computational-basis locus.

\section{Conclusion}
Three finite certificates explain cardinalities $19$, $21$, and $23$ at order six. Symmetry reduces a Schur-product square to $21$ unordered representatives. One triple collision lowers this to $19$; complete injectivity attains $21$. An orthogonal $4+2$ decomposition replaces symmetric counting by a disjoint union of $19$ and $4$ rays, producing $23$ and crossing the Schur-product ceiling.

Geometry and enumeration thereby separate cleanly. Hadamard identities or direct-sum arrangements establish orthonormal rows and columns. Fiber patterns, injectivity, and disjointness establish exact cardinality. This framework supports systematic study of the ray spectrum at order six and beyond.

