from typing import Hashable, TypeVar
T = TypeVar("T", bound=Hashable)
def symmetric_cardinality(n: int, labels: dict[tuple[int, int], T]) -> int:
    expected = {(i, j) for i in range(n) for j in range(i, n)}
    if set(labels) != expected:
        raise ValueError("incomplete upper triangle")
    return len(set(labels.values()))

from typing import Sequence
def canonical_ray(v: Sequence[complex], tol: float = 1e-10) -> tuple[tuple[float,float], ...]:
    norm = sum(abs(z)**2 for z in v)**0.5
    if norm <= tol: raise ValueError("zero vector")
    u = [z/norm for z in v]
    pivot = next(z for z in u if abs(z) > tol)
    phase = pivot.conjugate()/abs(pivot)
    return tuple((round((phase*z).real,10), round((phase*z).imag,10)) for z in u)
def ray_fibers(vectors: dict[tuple[int,int], Sequence[complex]]) -> dict[object,list[tuple[int,int]]]:
    out: dict[object,list[tuple[int,int]]] = {}
    for p,v in vectors.items(): out.setdefault(canonical_ray(v),[]).append(p)
    return out

from typing import Sequence
def support_tag(v: Sequence[complex], split: int = 4, tol: float = 1e-10) -> str:
    left = any(abs(z)>tol for z in v[:split]); right = any(abs(z)>tol for z in v[split:])
    if left and not right: return "C4"
    if right and not left: return "C2"
    if not left and not right: raise ValueError("zero vector")
    raise ValueError("mixed support")
def additive_cardinality(a: set[object], b: set[object]) -> int:
    if a & b: raise ValueError("not disjoint")
    return len(a)+len(b)

